                  ctx.lineWidth = 1.4;
                  ctx.beginPath();
                  ctx.moveTo(liveNodePt.x + 7, liveNodePt.y - 5);
                  ctx.lineTo(bx - 9, by + 5);
                  ctx.stroke();

                  ctx.shadowColor = 'rgba(15, 23, 42, 0.22)';
                  ctx.shadowBlur = 5;
                  ctx.shadowOffsetY = 1.5;
                  ctx.fillStyle = '#ef4444';
                  ctx.strokeStyle = '#ffffff';
                  ctx.lineWidth = 2;
                  ctx.beginPath();
                  ctx.arc(bx, by, 11.5, 0, Math.PI * 2);
                  ctx.fill();
                  ctx.stroke();

